/// <summary>
/// Extension of table <t>CustInvoiceTable</t>
/// </summary>
[ExtensionOf(tableStr(CustInvoiceTable))]
final class AVACustInvoiceTableDbt_Extension
{
}

Method.Source:
/// <summary>
/// Extension of method setInvoiceAddress
/// </summary>
void setInvoiceAddress()
{
    next setInvoiceAddress();

    CustTable custTableAddress = this.getInvoiceAddressAccount();

    this.Name = custTableAddress.avaName();

}

/// <summary>
///     AVA <c>modifiedField</c> method.
/// </summary>
/// <param name="_fieldId">
///     <c>FieldId</c> as type
/// </param>
public void modifiedField(FieldId _fieldId)
{

    next modifiedField(_fieldId);

    switch(_fieldId)
    {
        case fieldnum(CustInvoiceTable, AVABonusInvoice):
        case fieldnum(CustInvoiceTable, OrderAccount):
            if (this.AVABonusInvoice == NoYes::Yes)
            {
                this.AVABonusCustAccount    = this.OrderAccount;
                this.AVABonusAlliance       = this.custTable_OrderAccount().KCS_TOSId;
            }
            else
            {
                this.AVABonusCustAccount   = '';
                this.AVABonusAlliance      = '';
            }
            break;
    }
}

/// <summary>
///    AVA <c>displayCustomerOrAllianceName</c> method.
/// </summary>
/// <returns>
///     <c>CustName</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
public display CustName displayCustomerOrAllianceName()
{
    CustName    retVal;

    if(this.AVABonusAllocationBase == AVABonusAllocationBase::Customer)
    {
        retVal = CustTable::find(this.AVABonusCustAccount).name();
    }
    else if(this.AVABonusAllocationBase == AVABonusAllocationBase::Alliance)
    {
        retVal = KCS_TOSTable::find(this.AVABonusAlliance).Description;
    }

    return retVal;
}
